insert into t_lh_mold_change_plan_temp ( id, mold_batch_no, schedule_date, lh_machine_code, before_sap_code, before_spec_desc, tire_rough_stock, change_type, after_sap_code, after_spec_desc, stock_area, change_time, create_by, create_time, update_by, update_time, del_flag, source_cx_order, remark ) select seq_lh_mold_change_plan.NEXTVAL AS ID, x.* from (
